test('(e) uniquePhone + one attempt: the same phone on another device is refused in Arabic; no «حاول تاني»', async () => {

  const { call } = newWorld();
  scoredComp(call, { slug: 'once-quiz', uniquePhone: true, attempts: 1 });
  publish(world, call);

  let { context, page, problems } = await open('/competition/once-quiz/');
  await page.click('[data-cta]');
  const phone = await fillIdentity(page);
  await answerAll(page);
  await sendFromReview(page);
  await page.waitForSelector('.result__line--score');
  assert.equal(await page.evaluate(() => [...document.querySelectorAll('button')].some(b => b.textContent.includes('حاول مرة تانية'))), false);
  await context.close();

  ({ context, page, problems } = await open('/competition/once-quiz/'));
  await page.click('[data-cta]');
  await fillIdentity(page, phone, 'نفس الشخص');
  await waitState(page, 'identity');
  await page.waitForSelector('.alert, .field__error');
  const message = await page.evaluate(() => (document.querySelector('.alert') || document.querySelector('.field__error')).textContent);
  assert.match(message, /شارك|الحد|المحاولات/, message);
  assert.deepEqual(problems, []);
  await context.close();

});


/* =========================================================
   (f) shuffled order, still graded right
========================================================= */

test('(f) shuffleQ + shuffleC: each attempt has its own order, grading still right', async () => {

  const { call } = newWorld();
  scoredComp(call, { slug: 'shuffle-quiz', shuffleQ: true, shuffleC: true });
  publish(world, call);

  const orders = [];
  for (let i = 0; i < 2; i += 1) {
    const { context, page, problems, fns } = await open('/competition/shuffle-quiz/');
    await page.click('[data-cta]');
    await fillIdentity(page);
    await waitState(page, 'question');
    const qs = fns('compStart')[0].reply.questions;
    orders.push(JSON.stringify(qs.map(q => [q.id, q.choices.map(c => c.id)])));
    await answerAll(page);
    await sendFromReview(page);
    await page.waitForSelector('.result__line--score');
    assert.equal(await textOf(page, '.result__line--score'), 'درجتك ٣٥/٤٥');
    assert.deepEqual(problems, []);
    await context.close();
  }
  assert.notEqual(orders[0], orders[1], 'two attempts, two orders');

});


