test('(g) the generated stub: OG tags, the site CSP, data-slug/data-v, assets through ../../; (i) no answer key in any public file or compStart reply', async () => {

  const { call } = newWorld();
  const banner = call('apiUploadMedia', {
    full: readFileSync(`${ROOT}media/2026/img-592fd134.webp`).toString('base64'),
    thumb: readFileSync(`${ROOT}media/2026/img-592fd134-480.webp`).toString('base64'),
    mime: 'image/webp', width: 1448, height: 1086, alt: 'بانر المسابقة'
  }).media;
  const { id } = scoredComp(call, { slug: 'stub-quiz', title: 'مسابقة البانر', description: 'وصف المسابقة العام', banner: banner.id, theme: 'emerald' });
  const q = input => call('apiCompQuestionSave', id, input).question;
  q({ type: 'single', text: 'سؤال-سري-لايف', choices: [{ text: 'اختيار-سري-صح', correct: true }, { text: 'اختيار-سري-غلط' }], explanation: 'شرح-سري-لايف', points: 5 });
  q({ type: 'short', text: 'سؤال-قصير-سري', correct: ['مقبول-سري-لايف', 'مقبول-تاني-سري'], points: 5 });
  q({ type: 'number', text: 'سؤال-رقم-سري', correct: '987654', explanation: 'شرح-رقم-سري', points: 5 });
  publish(world, call);

  const files = world.github.files();
  const stub = String(files['competition/stub-quiz/index.html']);
  const def = JSON.parse(files['competition/stub-quiz/comp.json']);
  assert.match(stub, /<html lang="ar" dir="rtl" data-slug="stub-quiz" data-v="[0-9a-f]{16}">/);
  assert.equal(/data-v="([0-9a-f]{16})"/.exec(stub)[1], def.v);
  assert.equal(/<meta http-equiv="Content-Security-Policy" content="([^"]+)">/.exec(stub)[1], SITE_CSP, 'the site CSP');
  assert.match(stub, /<meta property="og:title" content="مسابقة البانر">/);
  assert.match(stub, new RegExp(`<meta property="og:url" content="${SITE}competition/stub-quiz/">`));
  assert.match(stub, new RegExp(`<meta property="og:image" content="${SITE}${def.banner.src}">`));
  assert.match(stub, /<link rel="canonical" href="https:\/\/stathanasiosyouth\.github\.io\/competition\/stub-quiz\/">/);
  assert.match(stub, /src="\.\.\/\.\.\/assets\/js\/comp\/main\.js"/);
  assert.equal((stub.match(/<title>/g) || []).length, 1, 'one title (the shell\'s replaced)');
  assert.doesNotMatch(stub, /="\.\.\/(?!\.\.\/)/, 'every relative URL one level deeper');

  const { context, page, problems, fns, outside } = await open('/competition/stub-quiz/');
  await waitState(page, 'intro');
  assert.equal(await page.evaluate(() => getComputedStyle(document.body).fontFamily.includes('Cairo')), true, 'comp.css loaded through ../../');
  assert.equal(await page.evaluate(() => document.documentElement.dataset.theme), 'emerald');
  await page.waitForFunction(() => { const img = document.querySelector('.hero__img'); return img && img.complete && img.naturalWidth > 0; });
  assert.deepEqual(served.filter(s => s.status !== 200).map(s => s.path), [], 'every asset found');
  assert.ok(served.some(s => s.path === `/${def.banner.thumb}`), 'the banner from the commit');

  // (i) the compStart reply: questions, never their key
  await page.click('[data-cta]');
  await fillIdentity(page);
  await waitState(page, 'question');
  const startText = fns('compStart')[0].text;
  for (const key of ['"correct"', '"explanation"', '"review"', '"explanationMedia"']) assert.ok(!startText.includes(key), `${key} in compStart`);
  for (const secret of ['مقبول-سري-لايف', 'مقبول-تاني-سري', 'شرح-سري-لايف', 'شرح-رقم-سري', '987654', 'التكوين']) assert.ok(!startText.includes(secret), `${secret} in compStart`);
  assert.ok(startText.includes('سؤال-سري-لايف'), 'the questions themselves are there');

  // every public file the browser can fetch
  const secrets = ['سؤال-سري-لايف', 'سؤال-قصير-سري', 'سؤال-رقم-سري', 'اختيار-سري-صح', 'اختيار-سري-غلط', 'مقبول-سري-لايف', 'مقبول-تاني-سري', 'شرح-سري-لايف', 'شرح-رقم-سري', '987654', 'مين بنى الفلك', 'نوح', 'التكوين', 'اكتب تأمل قصير'];
  for (const path of ['/content.json', '/competition/stub-quiz/comp.json', `/competition/stub-quiz/comp.json?v=${def.v}`, '/competition/stub-quiz/', '/competition/stub-quiz/index.html']) {
    const body = await page.evaluate(async p => (await fetch(p, { cache: 'no-store' })).text(), path);
    for (const secret of secrets) assert.ok(!body.includes(secret), `${secret} leaked in ${path}`);
  }
  for (const [path, value] of Object.entries(world.github.files())) {
    const body = Buffer.isBuffer(value) ? '' : String(value);
    for (const secret of secrets) assert.ok(!body.includes(secret), `${secret} committed in ${path}`);
  }
  assert.deepEqual(problems, []);
  assert.deepEqual(outside, []);
  await context.close();

});


/* =========================================================
   (h) the main page's card
========================================================= */

test('(h) the main page: a linked competition card opens the engine in the same tab', async () => {

  const { call } = newWorld();
  const { id } = scoredComp(call, { slug: 'card-quiz', title: 'مسابقة الكارت', startAt: wallAt(world, -10), endAt: wallAt(world, 3000), ctaLabel: 'يلا نلعب' });
  call('apiCompSave', id, { card: true });
  publish(world, call);
  const content = JSON.parse(world.github.files()['content.json']);
  const card = content.activities.find(a => a.competition === 'card-quiz');
  assert.ok(card, 'the linked card is published');
  assert.equal(card.cta, null);
  assert.equal(content.competitions[0].slug, 'card-quiz');

  const { context, page, problems } = await open('/');
  await page.waitForSelector('main[data-state="ready"]');
  const cta = await page.waitForSelector('.item-card__cta[data-competition="card-quiz"]');
  assert.deepEqual(await cta.evaluate(a => ({ href: a.getAttribute('href'), target: a.getAttribute('target'), text: a.textContent.trim() })), { href: 'competition/card-quiz/', target: null, text: 'يلا نلعب' });
  await Promise.all([page.waitForNavigation({ waitUntil: 'networkidle0' }), cta.evaluate(a => a.click())]);
  assert.equal(new URL(page.url()).pathname, '/competition/card-quiz/');
  await waitState(page, 'intro');
  assert.equal(await textOf(page, '.hero__title'), 'مسابقة الكارت');
  assert.deepEqual(problems.filter(p => !/Refused to apply inline style/.test(p)), []);
  await context.close();

});


/* =========================================================
   (j) manual review
========================================================= */

test('(j) a long answer waits for review: the participant sees it pending; after apiCompGrade, the final score', async () => {

  const { call } = newWorld();
  const { id, questions } = scoredComp(call, { slug: 'review-quiz', answersShow: 'never' });
  publish(world, call);

  const { context, page, problems } = await open('/competition/review-quiz/');
  await page.click('[data-cta]');
  await fillIdentity(page);
  await answerAll(page, { long: 'تأملي في قصة نوح' });
  await sendFromReview(page);
  await page.waitForSelector('.result__line--pending');
  assert.match(await textOf(page, '.result__line--pending'), /فيه إجابات بتتراجع/);
  assert.equal(await textOf(page, '.result__line--score'), 'درجتك ٣٥/٤٥');

  const sub = submissions(call, id).items[0];
  assert.equal(sub.status, 'pending_review');
  call('apiCompGrade', sub.id, { [questions.long.id]: 10 });

  await reload(page);
  await page.waitForSelector('.result__line--score');
  assert.equal(await textOf(page, '.result__line--score'), 'درجتك ٤٥/٤٥');
  assert.equal(await page.$('.result__line--pending'), null);
  assert.deepEqual(problems, []);
  await context.close();

});


